:root {
  --surface: #fcfcfb; --page: #f9f9f7; --ink: #0b0b0b; --ink-2: #52514e; --muted: #898781;
  --grid: #e1e0d9; --axis: #c3c2b7; --accent: #2a78d6; --wash: rgba(42, 120, 214, 0.08);
  --high: #0ca30c; --medium: #c98500; --low: #d03b3b;
  font: 14px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif; color: var(--ink);
}
* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; background: var(--page); }
#disclosure { padding: 6px 16px; background: #fff4d6; border-bottom: 1px solid #f0dfa8; font-size: 13px; }
#layout { display: grid; grid-template-columns: 290px 1fr auto; height: calc(100% - 31px); }
#controls { overflow-y: auto; padding: 14px 16px 24px; background: var(--surface); border-right: 1px solid var(--grid); }
#controls h1 { font-size: 17px; margin: 0 0 12px; line-height: 1.2; }
#controls h1 span { font-weight: 400; color: var(--ink-2); }
#controls .about { margin: -6px 0 12px; font-size: 13px; }
#controls .about a { color: var(--accent); }
#controls h2 { font-size: 12px; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); margin: 18px 0 6px; }
#controls label { display: block; font-size: 13px; color: var(--ink-2); margin: 6px 0; }
#controls select, #controls input[type="search"], #controls input[type="number"] {
  display: block; width: 100%; margin-top: 3px; padding: 5px 6px; font: inherit; color: var(--ink);
  border: 1px solid var(--axis); border-radius: 6px; background: #fff;
}
#controls .row { display: flex; gap: 6px; align-items: center; margin: 6px 0; }
#controls .row select, #controls .row input { width: auto; flex: 1; margin: 0; }
#controls .seg { display: flex; gap: 4px; }
#controls .seg label { flex: 1; margin: 0; padding: 4px 6px; border: 1px solid var(--axis); border-radius: 6px; text-align: center; cursor: pointer; }
#controls .seg label:has(input:checked) { background: var(--wash); border-color: var(--accent); color: var(--accent); font-weight: 600; }
#controls .seg input { display: none; }
#controls .check { display: flex; gap: 6px; align-items: center; }
button { font: inherit; padding: 5px 12px; border-radius: 6px; border: 1px solid var(--accent); background: var(--accent); color: #fff; cursor: pointer; }
button.ghost { background: transparent; color: var(--ink-2); border-color: var(--axis); }
button:focus-visible, select:focus-visible, input:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.filters { list-style: none; padding: 0; margin: 6px 0; font-size: 12px; }
.filters li { display: flex; justify-content: space-between; gap: 6px; align-items: center; padding: 4px 6px; background: var(--wash); border-radius: 6px; margin-bottom: 4px; }
.filters button { padding: 0 6px; }
.search { position: relative; }
#hits { list-style: none; margin: 2px 0 0; padding: 0; position: absolute; left: 0; right: 0; z-index: 5; background: #fff; border: 1px solid var(--grid); border-radius: 6px; box-shadow: 0 6px 20px rgba(0,0,0,.12); }
#hits:empty { display: none; }
#hits li { padding: 6px 8px; cursor: pointer; display: flex; justify-content: space-between; gap: 8px; }
#hits li span { color: var(--muted); font-size: 12px; }
#hits li:hover, #hits li:focus { background: var(--wash); }
29:button { font: inherit; padding: 5px 12px; border-radius: 6px; border: 1px solid var(--accent); background: var(--accent); color: #fff; cursor: pointer; }
30:button.ghost { background: transparent; color: var(--ink-2); border-color: var(--axis); }
31:button:focus-visible, select:focus-visible, input:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
34:.filters button { padding: 0 6px; }
41:.hint { font-size: 12px; color: var(--muted); margin: 4px 0; }
43:#map-wrap { position: relative; }
45:#status { position: absolute; z-index: 3; left: 12px; top: 12px; background: rgba(252,252,251,.94); padding: 5px 10px; border-radius: 6px; font-size: 12px; color: var(--ink-2); box-shadow: 0 1px 4px rgba(0,0,0,.1); }
46:#legend { position: absolute; z-index: 3; left: 12px; bottom: 28px; background: rgba(252,252,251,.96); padding: 10px 12px; border-radius: 8px; font-size: 12px; box-shadow: 0 1px 6px rgba(0,0,0,.12); max-width: 260px; }
77:.chart figcaption .hint { font-weight: 400; margin: 0; }
97:@media (max-width: 900px) {
100:  #map-wrap { height: 60vh; }
121:button.link { background: none; border: none; color: var(--accent); padding: 0; text-align: left; text-decoration: underline; text-underline-offset: 2px; }
122:button.tiny { padding: 1px 7px; font-size: 12px; }
143:#people-legend { position: absolute; z-index: 3; right: 12px; top: 112px; background: rgba(252,252,251,.96); padding: 10px 12px; border-radius: 8px; font-size: 12px; box-shadow: 0 1px 6px rgba(0,0,0,.12); max-width: 260px; }
149:.people-table { max-height: 340px; overflow: auto; border: 1px solid var(--grid); border-radius: 6px; }
150:.people-table table { border-collapse: collapse; font: 11px/1.3 ui-monospace, SFMono-Regular, Menlo, monospace; font-variant-numeric: tabular-nums; }
151:.people-table th { position: sticky; top: 0; background: var(--surface); text-align: left; font-weight: 600; color: var(--ink-2); border-bottom: 1px solid var(--axis); }
152:.people-table th, .people-table td { padding: 3px 8px; white-space: nowrap; border-bottom: 1px solid var(--grid); }

