// The person table: one row per synthetic person of the main run (one realisation),
// in a drawer over the bottom of the map. It follows the sidebar's "Show only people
// where" filters, pages 100 rows at a time, finds a person, family, household or parcel
// by ID, downloads every matching row as CSV, and clicking a row flies to that person.
import type { PeopleLayer, PeopleState } from "./people";

const PAGE = 100;
const KEY_COLS = 10;  // person_id … EMPLOYMENT, the columns of `synthpop persons`

export class PersonTable {
  private el: HTMLElement;
  private layer: PeopleLayer | null = null;
  private s: PeopleState | null = null;
  private onPick: (i: number) => void;
  private page = 0;
  private query = "";
  private rows: number[] = [];

  constructor(el: HTMLElement, onPick: (i: number) => void) {
    this.el = el;
    this.onPick = onPick;
  }

  get open() { return !this.el.hidden; }

  show(layer: PeopleLayer, s: PeopleState) {
    this.layer = layer;
    this.s = s;
    this.el.hidden = false;
    this.page = 0;
    this.mount();
    this.update();
  }

  hide() { this.el.hidden = true; }

  /** Filters or data points changed: recount the rows, keeping the search. */
  refresh() {
    if (!this.open || !this.layer) return;
    this.page = 0;
    this.update();
  }

  private mount() {
    this.el.innerHTML = `
      <header>
        <div class="pt-title"><b>Person table</b> <span class="src"></span></div>
        <input type="search" class="pt-find" placeholder="Find person, family, household or parcel ID" aria-label="Find by ID" autocomplete="off" value="${esc(this.query)}">
        <span class="pt-count" aria-live="polite"></span>
        <div class="pt-pager">
          <button class="ghost tiny" data-act="prev" aria-label="Previous page">‹</button>
          <button class="ghost tiny" data-act="next" aria-label="Next page">›</button>
        </div>
        <button class="tiny" data-act="csv">Download CSV</button>
        <button class="ghost tiny" data-act="close" aria-label="Close person table">×</button>
      </header>
      <div class="people-table pt-body"></div>
      <p class="hint pt-note">Family = the householder and their relatives by birth, marriage or adoption (Census definition). POVERTY_RATIO = income as % of the poverty line (501 = over 500%). Blank = outside the column's universe: no family; EDUCATION under 25; EMPLOYMENT under 16; POVERTY not determined (institutions, dorms, unrelated children under 15). Click a row to go to that person.</p>`;
    const q = this.el.querySelector<HTMLInputElement>(".pt-find")!;
    q.oninput = () => { this.query = q.value; this.page = 0; this.update(); };
    this.el.querySelector<HTMLButtonElement>('[data-act="prev"]')!.onclick = () => { this.page--; this.render(); };
    this.el.querySelector<HTMLButtonElement>('[data-act="next"]')!.onclick = () => { this.page++; this.render(); };
    this.el.querySelector<HTMLButtonElement>('[data-act="close"]')!.onclick = () => this.hide();
    this.el.querySelector<HTMLButtonElement>('[data-act="csv"]')!.onclick = () => this.download();
    this.el.querySelector<HTMLElement>(".pt-body")!.onclick = (e) => {
      const tr = (e.target as HTMLElement).closest<HTMLTableRowElement>("tr[data-i]");
      if (tr) this.onPick(+tr.dataset.i!);
    };
  }

  /** Rows passing the sidebar filters, then the ID search. */
  private update() {
    const layer = this.layer!, p = layer.p;
    const idx = Array.from(layer.visible(this.s!));
    const q = this.query.trim().replace(/\s+/g, "").toUpperCase();
    if (!q) this.rows = idx;
    else {
      // A number is an exact person, family or household ID; a parcel ID (e.g. "014 J001")
      // matches by prefix, ignoring spaces, once the search holds a letter.
      const n = /^\d+$/.test(q) ? Number(q) : NaN;
      const parcelHit = p.parcels.map((x) => { const k = x.replace(/\s+/g, "").toUpperCase(); return Number.isNaN(n) ? k.startsWith(q) : k === q; });
      this.rows = idx.filter((i) => i === n || p.family[i] === n || p.household[i] === n || parcelHit[p.parcel[i]]);
    }
    this.render();
  }

  private render() {
    const cols = this.layer!.columns();
    const pages = Math.max(1, Math.ceil(this.rows.length / PAGE));
    this.page = Math.min(Math.max(this.page, 0), pages - 1);
    const from = this.page * PAGE, to = Math.min(from + PAGE, this.rows.length);
    const body = this.rows.slice(from, to).map((i) =>
      `<tr data-i="${i}" tabindex="0">${cols.map(([, f], c) => `<td${c < KEY_COLS ? ' class="key"' : ""}>${esc(String(f(i)))}</td>`).join("")}</tr>`).join("");
    this.el.querySelector(".pt-body")!.innerHTML = `<table><thead><tr>${cols.map(([h], c) => `<th${c < KEY_COLS ? ' class="key"' : ""}>${esc(h)}</th>`).join("")}</tr></thead><tbody>${body}</tbody></table>`
      + (this.rows.length ? "" : `<p class="empty">No synthetic people match.</p>`);
    const total = this.layer!.p.count;
    const filtered = this.rows.length !== total ? ` (of ${total.toLocaleString()})` : "";
    this.el.querySelector(".pt-count")!.textContent = this.rows.length
      ? `${(from + 1).toLocaleString()}–${to.toLocaleString()} of ${this.rows.length.toLocaleString()} people${filtered}` : `0 people${filtered}`;
    const run = this.layer!.run;
    this.el.querySelector(".pt-title .src")!.textContent = `one realisation (${run === "main" ? "main run" : `run ${run}`})`;
    this.el.querySelector<HTMLButtonElement>('[data-act="prev"]')!.disabled = this.page === 0;
    this.el.querySelector<HTMLButtonElement>('[data-act="next"]')!.disabled = this.page >= pages - 1;
  }

  private download() {
    const url = URL.createObjectURL(new Blob([this.layer!.csv(this.rows)], { type: "text/csv" }));
    const a = Object.assign(document.createElement("a"), { href: url, download: `persons_${this.layer!.run}.csv` });
    a.click();
    URL.revokeObjectURL(url);
  }
}

const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]!);

// The simulation player: steps the people layer through every saved run (main, 20
// placement draws, 80 replicates, validation) like a video. Runs load on demand and the
// next few are fetched ahead, so playback only waits when the network is slow.
import { getPeople, type People, type PeopleRun } from "./api";

const AHEAD = 3;          // runs fetched ahead of the playhead
const KEEP = 8;           // runs kept in memory

/** What a run is, in words. */
export function describeRun(r: PeopleRun, runs: PeopleRun[]): string {
  const n = Number(r.name.split("_")[1]);
  const of = (kind: string) => runs.filter((x) => x.kind === kind).length;
  switch (r.kind) {
    case "main": return "Main run: the one in the person table and on the map by default";
    case "draw": return `Placement draw ${n} of ${of("draw")}: same fit, households rounded and placed on parcels differently`;
    case "replicate": return `Replicate ${n} of ${of("replicate")}: refitted with Census survey weight set ${n} and its targets`;
    case "validation": return "Validation run: some blocks hidden from the model, to test placement";
    default: return r.name;
  }
}

export class Player {
  private el: HTMLElement;
  private runs: PeopleRun[];
  private onFrame: (p: People, run: PeopleRun, i: number) => void;
  private onClose: () => void;
  private cache = new Map<string, Promise<People>>();
  private i = 0;
  private playing = false;
  private timer: number | null = null;
  private fps = 1;
  private shown = -1;

  constructor(el: HTMLElement, runs: PeopleRun[], main: People,
              onFrame: (p: People, run: PeopleRun, i: number) => void, onClose: () => void) {
    this.el = el;
    this.runs = runs;
    this.onFrame = onFrame;
    this.onClose = onClose;
    this.cache.set("main", Promise.resolve(main));
  }

  get open() { return !this.el.hidden; }

  show() {
    this.el.hidden = false;
    this.mount();
    this.go(this.i);
  }

  hide() {
    this.pause();
    this.el.hidden = true;
    this.onClose();
  }

  private mount() {
    const max = this.runs.length - 1;
    this.el.innerHTML = `
      <div class="pl-row">
        <button class="pl-play" data-act="play" aria-label="Play">▶</button>
        <button class="ghost tiny" data-act="prev" aria-label="Previous run">‹</button>
        <button class="ghost tiny" data-act="next" aria-label="Next run">›</button>
        <input type="range" class="pl-scrub" min="0" max="${max}" step="1" value="${this.i}" aria-label="Run">
        <span class="pl-count"></span>
        <select class="pl-speed" aria-label="Speed">
          <option value="0.5">0.5 runs/s</option><option value="1" selected>1 run/s</option>
          <option value="2">2 runs/s</option><option value="4">4 runs/s</option>
        </select>
        <button class="ghost tiny" data-act="close" aria-label="Close player">×</button>
      </div>
      <div class="pl-label" aria-live="polite"></div>
      <div class="pl-ticks" aria-hidden="true">${this.runs.map((r) => `<i class="k-${r.kind}"></i>`).join("")}</div>`;
    const $ = <T extends HTMLElement>(sel: string) => this.el.querySelector<T>(sel)!;
    $<HTMLButtonElement>('[data-act="play"]').onclick = () => (this.playing ? this.pause() : this.play());
    $<HTMLButtonElement>('[data-act="prev"]').onclick = () => { this.pause(); this.go(this.i - 1); };
    $<HTMLButtonElement>('[data-act="next"]').onclick = () => { this.pause(); this.go(this.i + 1); };
    $<HTMLButtonElement>('[data-act="close"]').onclick = () => this.hide();
    $<HTMLInputElement>(".pl-scrub").oninput = (e) => { this.pause(); this.go(+(e.target as HTMLInputElement).value); };
    $<HTMLSelectElement>(".pl-speed").value = String(this.fps);
    $<HTMLSelectElement>(".pl-speed").onchange = (e) => {
      this.fps = +(e.target as HTMLSelectElement).value;
      if (this.playing) { this.pause(); this.play(); }
    };
  }

  private load(name: string): Promise<People> {
    let p = this.cache.get(name);
    if (!p) {
      p = getPeople(name);
      p.catch(() => this.cache.delete(name));
      this.cache.set(name, p);
      // Forget the oldest runs, but never the main run.
      for (const k of this.cache.keys()) {
        if (this.cache.size <= KEEP) break;
        if (k !== "main" && k !== name) this.cache.delete(k);
      }
    }
    return p;
  }

  /** Show run i (wrapping around), then fetch the next few. */
  private async go(i: number) {
    const n = this.runs.length;
    this.i = ((i % n) + n) % n;
    const run = this.runs[this.i];
    this.status(run, true);
    try {
      const p = await this.load(run.name);
      if (this.runs[this.i] !== run) return;          // the user moved on meanwhile
      this.shown = this.i;
      this.onFrame(p, run, this.i);
      this.status(run, false);
    } catch (e) {
      this.el.querySelector(".pl-label")!.textContent = `Could not load ${run.name}: ${(e as Error).message}`;
      this.pause();
    }
    for (let k = 1; k <= AHEAD; k++) this.load(this.runs[(this.i + k) % n].name);
  }

  private status(run: PeopleRun, loading: boolean) {
    const main = this.runs[0];
    const diff = run.people - main.people;
    this.el.querySelector<HTMLInputElement>(".pl-scrub")!.value = String(this.i);
    this.el.querySelector(".pl-count")!.textContent = `${this.i + 1} / ${this.runs.length}`;
    this.el.querySelector(".pl-label")!.innerHTML = `<b>${run.name}</b> · ${describeRun(run, this.runs)}<br>
      <span>${run.people.toLocaleString()} people${run.kind === "main" ? "" : ` (${diff >= 0 ? "+" : ""}${diff.toLocaleString()} vs main)`},
      ${run.households.toLocaleString()} households${loading ? " · loading…" : ""}</span>`;
    this.el.querySelectorAll(".pl-ticks i").forEach((t, k) => t.classList.toggle("on", k === this.i));
  }

  play() {
    this.playing = true;
    const b = this.el.querySelector<HTMLButtonElement>('[data-act="play"]')!;
    b.textContent = "❚❚"; b.setAttribute("aria-label", "Pause");
    const tick = async () => {
      if (!this.playing) return;
      const started = performance.now();
      await this.go(this.shown + 1);
      if (!this.playing) return;
      // Wait out the rest of the frame; a slow load just makes this frame longer.
      this.timer = window.setTimeout(tick, Math.max(0, 1000 / this.fps - (performance.now() - started)));
    };
    this.timer = window.setTimeout(tick, 1000 / this.fps);
  }

  pause() {
    this.playing = false;
    if (this.timer !== null) { clearTimeout(this.timer); this.timer = null; }
    const b = this.el.querySelector<HTMLButtonElement>('[data-act="play"]');
    if (b) { b.textContent = "▶"; b.setAttribute("aria-label", "Play"); }
  }
}

