1	// The people layer: every synthetic person of the main run as a dot on their E911
2	// address point, stacked upward where several share one (apartment buildings). By default
3	// each address point splits into side-by-side columns, one per colour group (e.g. one per
4	// age band), so a building reads as a small bar chart of who lives there.
5	// Everything after the one download runs in the browser, so colouring, filtering and
6	// data points react instantly. A data point marks a person a case when their fixed
7	// draw u is below their risk, so moving a slider adds or removes cases at the margin
8	// instead of reshuffling who has the condition.
9	import { ScatterplotLayer } from "@deck.gl/layers";
10	import type { People, RiskModel, Schema } from "./api";
11	
12	type RGB = [number, number, number];
13	const hex = (h: string): RGB => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16)) as RGB;
14	
15	// Categorical slots in fixed order, checked with the dataviz palette validator on the
16	// light surface (contrast is below 3:1 for some, so the legend labels every colour).
17	const SLOTS = ["#2a78d6", "#eb6834", "#1baf7a", "#eda100", "#e87ba4", "#008300", "#6250d6", "#e34948"].map(hex);
18	const BLANK: RGB = [175, 175, 170];
19	const CASE = SLOTS[1], NO_CASE = SLOTS[0];
20	
21	export const MIN_ZOOM = 14;          // people show from block zoom down
22	const FLOOR_M = 2.5;                 // height between people stacked on one address point
23	const COLUMN_GAP_PX = 2;             // space between side-by-side columns, beyond one dot
24	const DRAFT = "__draft";
25	
26	export type PeopleFilter = { by: string; values: string[] };
27	export type Focus = { level: string; id: string };
28	// focus: the area open in the detail panel; people outside it are faded.
29	// stack: "split" puts each colour group in its own column at an address point; "single"
30	// keeps one column with the groups in bands, lowest category at the bottom.
31	export type Stack = "split" | "single";
32	// anyZoom: show people at every zoom (while the simulation player is open), not only from block zoom.
33	export type PeopleState = { show: boolean; colorBy: string; filters: PeopleFilter[]; focus?: Focus | null; stack?: Stack; anyZoom?: boolean };
34	
35	export const peopleVisible = (s: PeopleState, zoom: number) => s.show && (zoom >= MIN_ZOOM || !!s.anyZoom);
36	
37	type Cat = { id: string; label: string };
38	/** Something to colour or filter people by: a data point, an attribute or the age band. */
39	export type Dim = { id: string; label: string; kind: "datapoint" | "attribute"; cats: Cat[]; code: (i: number) => number };
40	
41	const AGE_BANDS: [string, number][] = [["Under 18", 18], ["18–34", 35], ["35–64", 65], ["65+", Infinity]];
42	const DP_CATS: Cat[] = [{ id: "1", label: "Case" }, { id: "0", label: "Not a case" }, { id: "na", label: "Outside the model's universe" }];
43	
44	export class PeopleLayer {
45	  p: People;
46	  run = "main";                      // which saved run p is (the simulation player swaps it)
47	  private schema: Schema;
48	  private outcomes = new Map<string, { model: RiskModel; key: string; v: Uint8Array }>();  // 0 case, 1 not, 2 outside
49	  // grp: each visible person's colour group (category index; cats.length for blank).
50	  private view: { key: string; idx: Uint32Array; grp: Uint16Array; col: Uint8Array; counts: number[] } | null = null;
51	  private placed: { key: string; pos: Float64Array } | null = null;
52	
53	  constructor(p: People, schema: Schema) {
54	    this.p = p;
55	    this.schema = schema;
56	    this.setSchema(schema);
57	  }
58	
59	  /** Saved data points become person variables automatically; unchanged ones are kept. */
60	  setSchema(schema: Schema) {
61	    this.schema = schema;
62	    const saved = schema.variables.filter((v) => v.kind === "datapoint" && v.model).map((v) => v.model!);
63	    for (const id of [...this.outcomes.keys()]) if (id !== DRAFT && !saved.some((m) => m.id === id)) this.outcomes.delete(id);
64	    for (const m of saved) this.apply(m.id, m);
65	    this.view = null;
66	  }
67	
68	  /** Swap in another run's people (the simulation player). Data points are reapplied to them. */
69	  setPeople(p: People, run: string) {
70	    this.p = p;
71	    this.run = run;
72	    for (const o of this.outcomes.values()) o.v = outcomes(p, this.schema, o.model);
73	    this.view = null;
74	    this.placed = null;
75	  }
