77	  /** The data point being edited, recomputed on every slider move; null removes it. */
78	  setDraft(m: RiskModel | null) {
79	    if (m) this.apply(DRAFT, m); else this.outcomes.delete(DRAFT);
80	    this.view = null;
81	  }
