83	  private apply(id: string, m: RiskModel) {
84	    const key = JSON.stringify(m);
85	    if (this.outcomes.get(id)?.key === key) return;
86	    this.outcomes.set(id, { model: m, key, v: outcomes(this.p, this.schema, m) });
87	  }
