89	  dims(): Dim[] {
90	    const dps: Dim[] = [...this.outcomes].map(([id, o]) => ({
91	      id: `dp:${id}`, label: id === DRAFT ? `${o.model.label} (draft)` : o.model.label, kind: "datapoint", cats: DP_CATS,
92	      code: (i: number) => o.v[i],
93	    }));
94	    const age: Dim = { id: "age_band", label: "Age", kind: "attribute", cats: AGE_BANDS.map(([l]) => ({ id: l, label: l })),
95	      code: (i) => { const a = this.p.age[i]; return a < 0 ? -1 : AGE_BANDS.findIndex(([, hi]) => a < hi); } };
96	    const attrs: Dim[] = this.p.attributes.flatMap((a) => {
97	      const v = this.schema.variables.find((x) => x.id === a);
98	      if (!v) return [];
99	      const codes = this.p.codes[a];
100	      return [{ id: a, label: v.label, kind: "attribute" as const, cats: v.categories, code: (i: number) => codes[i] }];
101	    });
102	    return [...dps, age, ...attrs];
103	  }
