105	  dim(id: string) { return this.dims().find((d) => d.id === id); }
106	  static colourable(d: Dim) { return d.kind === "datapoint" || d.cats.length <= SLOTS.length; }
107	  draftId() { return this.outcomes.has(DRAFT) ? `dp:${DRAFT}` : null; }
