113	  /** Visible people (those passing every filter), their colours and groups, and counts per colour. */
114	  private compute(s: PeopleState) {
115	    const key = this.run + JSON.stringify({ ...s, anyZoom: undefined });
116	    if (this.view?.key === key) return this.view;
117	    const n = this.p.count;
118	    const checks = s.filters.flatMap((f) => {
119	      const d = this.dim(f.by);
120	      if (!d) return [];
121	      const ok = new Set(f.values.map((v) => d.cats.findIndex((c) => c.id === v)));
122	      return [(i: number) => ok.has(d.code(i))];
123	    });
124	    const keep: number[] = [];
125	    for (let i = 0; i < n; i++) if (checks.every((c) => c(i))) keep.push(i);
126	    const idx = Uint32Array.from(keep);
127	    const d = this.dim(s.colorBy) ?? this.dims()[0];
128	    const pal = this.colours(d);
129	    const inFocus = s.focus ? this.matcher(s.focus) : null;
130	    const counts = new Array(d.cats.length + 1).fill(0);
131	    const grp = new Uint16Array(idx.length);
132	    const col = new Uint8Array(idx.length * 4);
133	    for (let j = 0; j < idx.length; j++) {
134	      const i = idx[j];
135	      const c = d.code(i);
136	      const rgb = c >= 0 && c < pal.length ? pal[c] : BLANK;
137	      grp[j] = c >= 0 && c < pal.length ? c : d.cats.length;
138	      counts[grp[j]]++;
139	      // Outside a data point's universe (e.g. under 65 for dementia) stays faint, so cases stand out.
140	      const faint = (d.kind === "datapoint" && c === 2) || (inFocus !== null && !inFocus(i));
141	      col.set([...rgb, faint ? 45 : 225], j * 4);
142	    }
143	    this.view = { key, idx, grp, col, counts };
144	    return this.view;
145	  }
146	
147	  /** Lon, lat and height for each visible person. People at one address point stack upward
148	   * 2.5 m apart; split, each colour group gets its own column, ordered by category from west
149	   * to east and centred on the point. Columns are spaced in screen pixels, so they touch
150	   * without overlapping at any zoom. Only visible people stack, so filters leave no gaps. */
151	  private positions(v: NonNullable<PeopleLayer["view"]>, s: PeopleState, zoom: number, radius: number): Float64Array {
152	    const split = (s.stack ?? "split") === "split" && zoom >= MIN_ZOOM;
153	    const z = Math.round(zoom * 4) / 4;
154	    const key = `${v.key}|${split}|${split ? z : ""}|${radius}`;
155	    if (this.placed?.key === key) return this.placed.pos;
156	    const p = this.p, n = v.idx.length, pos = new Float64Array(n * 3);
157	    const at = new Map<string, number[]>();
158	    for (let j = 0; j < n; j++) {
159	      const i = v.idx[j], k = `${p.lon[i]},${p.lat[i]}`;
160	      const list = at.get(k);
161	      if (list) list.push(j); else at.set(k, [j]);
162	    }
163	    for (const js of at.values()) {
164	      const i0 = v.idx[js[0]], lon = p.lon[i0], lat = p.lat[i0];
165	      const cos = Math.cos((lat * Math.PI) / 180);
166	      const gapM = (2 * radius + COLUMN_GAP_PX) * (156543.03 * cos) / 2 ** z;     // web-mercator metres per pixel
167	      const dLon = gapM / (111320 * cos);
168	      js.sort((a, b) => v.grp[a] - v.grp[b] || a - b);
169	      const groups = split ? [...new Set(js.map((j) => v.grp[j]))] : [0];
170	      const level = new Map<number, number>();
171	      for (const j of js) {
172	        const g = split ? v.grp[j] : 0, h = level.get(g) ?? 0;
173	        level.set(g, h + 1);
174	        const slot = groups.indexOf(g) - (groups.length - 1) / 2;
175	        pos[j * 3] = lon + slot * dLon; pos[j * 3 + 1] = lat; pos[j * 3 + 2] = h * FLOOR_M;
176	      }
177	    }
178	    this.placed = { key, pos };
179	    return pos;
180	  }
