182	  /** onParcel: clicking a dot opens the parcel it lives on. */
183	  layer(zoom: number, s: PeopleState, onParcel?: (parcelId: string) => void): ScatterplotLayer | null {
184	    if (!peopleVisible(s, zoom)) return null;
185	    const v = this.compute(s);
186	    const radius = zoom >= 16 ? 3 : zoom >= MIN_ZOOM ? 2 : 1.5;
187	    const pos = this.positions(v, s, zoom, radius);
188	    return new ScatterplotLayer({
189	      id: "people",
190	      data: { length: v.idx.length, attributes: {
191	        getPosition: { value: pos, size: 3 }, getFillColor: { value: v.col, size: 4 },
192	      } },
193	      billboard: true, radiusUnits: "pixels", getRadius: radius, stroked: false, pickable: true,
194	      onClick: (info) => { const i = this.person(info.index); if (i >= 0 && onParcel) onParcel(this.p.parcels[this.p.parcel[i]]); },
195	      updateTriggers: { getRadius: zoom >= 16 },
