199	  /** Tests whether a person lives in an area. Block ids begin with their tract (11 digits)
200	   * and block group (12), so every level but parcel and city is a prefix of the block. */
201	  matcher(f: Focus): (i: number) => boolean {
202	    const p = this.p;
203	    if (f.level === "parcel") { const k = p.parcels.indexOf(f.id); return (i) => p.parcel[i] === k; }
204	    if (["block", "block_group", "tract"].includes(f.level)) {
205	      const ok = p.blocks.map((b) => b.startsWith(f.id));
206	      return (i) => ok[p.block[i]];
207	    }
208	    return () => f.level === "city";
209	  }
