218	   * The first ten match `synthpop persons`: IDs, exact age, sex, race, education, poverty and employment. */
219	  columns(): [string, (i: number) => string | number][] {
220	    const p = this.p, dims = this.dims();
221	    const cat = (id: string) => { const d = dims.find((x) => x.id === id); return (i: number) => { const c = d ? d.code(i) : -1; return c >= 0 ? d!.cats[c].id : ""; }; };
222	    return [
223	      ["person_id", (i) => i],
224	      ["family_id", (i) => (p.family[i] >= 0 ? p.family[i] : "")],
225	      ["parcel_id", (i) => p.parcels[p.parcel[i]]],
226	      ["AGE", (i) => p.age[i]],
227	      ["SEX", cat("sex")],
228	      ["RACE", cat("race_eth")],
229	      ["EDUCATION", cat("education")],
230	      ["POVERTY", cat("poverty")],
231	      ["POVERTY_RATIO", (i) => (p.poverty_ratio[i] >= 0 ? p.poverty_ratio[i] : "")],
232	      ["EMPLOYMENT", cat("employment")],
233	      ["household_id", (i) => (p.household[i] >= 0 ? p.household[i] : "")],
234	      ["block", (i) => p.blocks[p.block[i]]],
235	      ["lon", (i) => p.lon[i]],
236	      ["lat", (i) => p.lat[i]],
237	      ["location", (i) => (p.fallback[i] ? "parcel" : "address")],
238	      ...dims.filter((d) => d.kind === "datapoint").map((d) =>
239	        [d.id.slice(3), (i: number) => ["1", "0", ""][d.code(i)]] as [string, (i: number) => string]),
240	    ];
241	  }
