312	/** 0 case, 1 not a case, 2 outside the universe, for every person (as synthpop/datapoints.py). */
313	function outcomes(p: People, schema: Schema, m: RiskModel): Uint8Array {
314	  const cats = (f: string) => schema.variables.find((v) => v.id === f)?.categories.map((c) => c.id) ?? [];
315	  const logOr = Object.entries(m.odds_ratios).map(([f, ors]) => [p.codes[f], cats(f).map((c) => Math.log(ors[c] ?? 1))] as const);
316	  const inside = Object.entries(m.universe).map(([f, allowed]) => [p.codes[f], cats(f).map((c) => allowed.includes(c))] as const);
317	  const base = Math.log(m.baseline / (1 - m.baseline));
318	  const out = new Uint8Array(p.count);
319	  for (let i = 0; i < p.count; i++) {
320	    if (!inside.every(([codes, ok]) => codes && codes[i] >= 0 && ok[codes[i]])) { out[i] = 2; continue; }
321	    let l = base;
322	    for (const [codes, lo] of logOr) if (codes && codes[i] >= 0) l += lo[codes[i]];
323	    out[i] = p.u[i] < 1 / (1 + Math.exp(-l)) ? 0 : 1;
324	  }
325	  return out;
326	}
