414	  };
415	  renderFilters();
416	  $<HTMLButtonElement>("pp-table").onclick = () => onTable?.();
417	  $<HTMLButtonElement>("pp-player").onclick = () => onPlayer?.();
418	  $<HTMLInputElement>("pp-show").onchange = (e) => { s.show = (e.target as HTMLInputElement).checked; onChange(); };
419	  $<HTMLSelectElement>("pp-color").onchange = (e) => { s.colorBy = (e.target as HTMLSelectElement).value; onChange(); };
420	  $<HTMLSelectElement>("pp-stack").onchange = (e) => { s.stack = (e.target as HTMLSelectElement).value as Stack; onChange(); };
421	  $<HTMLSelectElement>("pp-fdim").onchange = (e) => { $("pp-fcat").innerHTML = catOpts((e.target as HTMLSelectElement).value); };
422	  $("pp-fadd").onclick = () => {
423	    const by = $<HTMLSelectElement>("pp-fdim").value, value = $<HTMLSelectElement>("pp-fcat").value;
424	    const same = s.filters.find((f) => f.by === by);
425	    if (same) { if (!same.values.includes(value)) same.values.push(value); }
426	    else s.filters.push({ by, values: [value] });
427	    renderFilters();
428	    onChange();
