64	        return i >= 0 ? { html: people!.tooltip(i), className: "tip" } : null;
65	      }
66	      const object = info.object;
67	      const id = object?.properties?.id as string | undefined;
68	      const v = id && current.color?.values[id];
69	      if (!id) return null;
70	      const label = editing ? { label: editing.model.label, kind: "total" } : schema.variables.find((x) => x.id === state.variable);
71	      const cat = editing ? "" : label && "categories" in label ? label.categories.find((c) => c.id === state.category)?.label ?? "" : "";
72	      return {
73	        html: `<b>${levelLabel(schema.levels, current.level)}</b> ${id}<br>${label?.label}${label?.kind === "total" || label?.kind === "datapoint" ? "" : ": " + cat}<br>` +
74	          (v ? `${fmt(v[0], state.measure)} ± ${fmt(1.645 * v[1], state.measure)} · ${v[2]} confidence` : "none placed") +
