85	  let seq = 0;
86	  let cityRate: number | null = null;
87	
88	  // People: every synthetic person as a dot. Data points apply to them in the browser,
89	  // so the dots recolour and filter as soon as a data point is added or a slider moves.
90	  // colorBy starts empty, so people open coloured by the first saved data point (else age).
91	  const pstate: PeopleState = { show: true, colorBy: "", filters: [], stack: "split" };
92	  let people: PeopleLayer | null = null;
93	  const peopleSection = document.createElement("section");
94	  peopleSection.className = "people";
95	  const peopleLegend = document.getElementById("people-legend")!;
96	  let areaArgs: Parameters<typeof renderLevel> | null = null;
97	  let areaLayer: ReturnType<typeof renderLevel> | null = null;
98	  let areaFaded = false;
99	  const peopleOn = () => !!people && peopleVisible(pstate, map.getZoom());
100	  // The simulation player swaps the people layer through every saved run; closing it goes back to main.
101	  let player: Player | null = null;
102	  let mainPeople: People | null = null;
103	  // The person table: clicking a row flies to that person and opens their parcel.
104	  const personTable = new PersonTable(document.getElementById("person-table")!, (i) => {
105	    if (!people) return;
