107	    map.flyTo({ center: [people.p.lon[i], people.p.lat[i]], zoom: Math.max(map.getZoom(), 17.5), speed: 1.4 });
108	    openDetail("parcel", people.p.parcels[people.p.parcel[i]]);
109	  });
110	
111	  function draw() {
112	    const fade = peopleOn();
113	    if (areaArgs && (!areaLayer || fade !== areaFaded)) {
114	      const [level, geometry, color, extrude, opts] = areaArgs;
115	      areaLayer = renderLevel(level, geometry, color, extrude, { ...opts, fade });
116	      areaFaded = fade;
117	    }
118	    const pl = people?.layer(map.getZoom(), pstate, (parcel) => openDetail("parcel", parcel));
119	    overlay.setProps({ layers: [areaLayer, pl].filter(Boolean) });
120	    people?.legend(peopleLegend, pstate, map.getZoom());
121	    personTable.refresh();
122	  }
123	
124	  function mountPeople() {
