126	    const after = controls.querySelector(".datapoints") ?? controls.querySelector(".search");
127	    after?.after(peopleSection);
128	    mountPeopleControls(peopleSection, people, pstate, draw, () => people && personTable.show(people, pstate),
129	      player ? () => { pstate.show = true; pstate.anyZoom = true; player!.show(); draw(); } : undefined);
