138	    if (!ids.has(pstate.colorBy)) pstate.colorBy = people.dims().find((d) => d.kind === "datapoint")?.id ?? "age_band";
139	    mountPeople();
140	    draw();
141	  }
142	
143	  async function refresh() {
144	    const my = ++seq;
145	    const level = levelForZoom(schema.levels, map.getZoom()).id;
146	    status.textContent = `Loading ${levelLabel(schema.levels, level).toLowerCase()}s…`;
147	    const heightVar = state.height === "color" ? state.variable : state.height;
148	    const heightCat = state.height === "color" ? state.category : "total";
149	    const measure = editing ? "share" : state.measure;     // a draft data point is shown as its rate
150	    const vsCity = state.scheme === "vs_city" && measure === "share";
151	    const colorReq = editing
152	      ? previewDatapoint(editing.model, level, measure, state.filters)
153	      : getLayer(level, state.variable, state.category, state.measure, state.filters);
154	    const [geometry, color, extrude, city] = await Promise.all([
155	      getGeometry(level),
156	      colorReq,
157	      state.height === "none" ? Promise.resolve(null) : getLayer(level, heightVar, heightCat, "estimate", []),
158	      vsCity && !editing ? getLayer("city", state.variable, state.category, "share", []) : Promise.resolve(null),
159	    ]).catch((e) => { editing?.editor.showError(e.message); status.textContent = e.message; throw e; });
160	    if (vsCity && editing) {            // compare with the Portland-wide rate of the draft
161	      const p = color as Awaited<ReturnType<typeof previewDatapoint>>;
162	      cityRate = p.city.share;
163	    } else cityRate = null;
164	    if (my !== seq) return;                       // a newer refresh started meanwhile
165	    if (editing) editing.editor.showResult(color as Awaited<ReturnType<typeof previewDatapoint>>);
166	    current = { level, color };
167	    const scheme = vsCity ? "vs_city" : state.scheme === "vs_city" ? "green_blue" : state.scheme;
168	    const reference = city ? Object.values(city.values)[0]?.[0] ?? 0 : cityRate;
169	    const breaks = reference !== null
170	      ? divergingBreaks(Object.values(color.values).filter((v) => v[0] > 0).map((v) => v[0] - reference))
171	      : color.breaks;
172	    areaArgs = [level, geometry, color, extrude, {
173	      extruded: state.extruded, confidence: state.confidence, selected, scheme, reference, breaks,
174	      onClick: (id) => openDetail(level, id),
175	    }];
176	    areaLayer = null;
177	    draw();
178	    const v = schema.variables.find((x) => x.id === state.variable)!;
179	    const title = editing
180	      ? `${editing.model.label} (draft) ${measure === "share" ? "(rate)" : "(expected cases)"}`
181	      : `${v.label}${v.kind === "total" || v.kind === "datapoint" ? "" : " · " + v.categories.find((c) => c.id === state.category)?.label}` +
182	        (state.measure === "share" ? (v.kind === "datapoint" ? " (rate)" : " (share)") : v.kind === "datapoint" ? " (expected cases)" : " (count)");
183	    const heightLabel = state.height === "none" || !state.extruded ? null
184	      : state.height === "color" ? "selected category" : { population: "people", households: "households", housing_units: "housing units" }[state.height];
185	    renderLegend(legend, title, color as LayerValues, state.confidence, heightLabel, scheme, breaks, reference);
186	    const n = Object.keys(color.values).length;
187	    status.textContent = `${levelLabel(schema.levels, level)} level · ${n.toLocaleString()} areas` +
188	      (color.filtered_count !== null ? ` · ${color.filtered_count.toLocaleString()} match filters` : "") +
189	      ` · zoom ${map.getZoom().toFixed(1)}`;
190	  }
191	
192	  async function openDetail(level: string, id: string) {
193	    selected = id;
194	    const draft = editing?.model ?? null;
195	    const d = draft ? await previewDetail(level, id, draft) : await getDetail(level, id);
196	    showDetail(panel, d, schema, () => {
197	      selected = null;
198	      pstate.focus = null;
199	      if (draft) startEditing(draft, isSavedId(draft.id)); else { panel.hidden = true; refresh(); }
200	    }, draft ? "Back to editor" : undefined);
201	    if (people && level !== "county" && level !== "state") {
202	      // The clicked area's own people: summary, table and CSV; people elsewhere fade on the map.
203	      const focus = { level, id };
204	      pstate.focus = level === "city" ? null : focus;
205	      const here = document.createElement("section");
206	      panel.querySelector("p.hint")?.after(here);
207	      const show = () => map.flyTo({ center: [d.area.lon, d.area.lat], zoom: Math.max(map.getZoom(), PEOPLE_ZOOM[level] ?? MIN_ZOOM), speed: 1.4 });
208	      mountPeopleHere(here, people, focus, show);
209	      // Clicking a structure while zoomed out goes straight to its people.
210	      if (pstate.show && map.getZoom() < MIN_ZOOM && level !== "city") show();
211	    }
212	    refresh();
213	  }
214	
215	  const isSavedId = (id: string) => schema.variables.some((v) => v.kind === "datapoint" && v.id === id);
216	
217	  function startEditing(model: RiskModel, saved: boolean) {
218	    // While a slider moves, keep one preview in flight; when it lands, send the latest model.
219	    let inFlight = false, again = false;
220	    const preview = () => {
221	      inFlight = true;
222	      refresh().catch(() => {}).then(() => {
223	        if (again) { again = false; preview(); } else inFlight = false;
224	      });
225	    };
226	    const editor = openEditor(panel, schema, model, saved, {
227	      onChange: (m) => {
228	        if (editing) editing.model = m;
229	        people?.setDraft(m);
230	        draw();
231	        if (inFlight) again = true; else preview();
232	      },
233	      onSave: async (m) => {
234	        await saveDatapoint(m);
235	        schema = await getSchema();
236	        editing = null;
237	        panel.hidden = true;
238	        Object.assign(state, { variable: m.id, category: "yes", measure: "share" });
239	        for (const f of pstate.filters) if (f.by === people?.draftId()) f.by = `dp:${m.id}`;
240	        people?.setDraft(null);
241	        people?.setSchema(schema);
242	        remountControls();
243	        syncPeople(`dp:${m.id}`);
244	        refresh();
245	      },
246	      onClose: () => {
247	        // Filters that followed the draft go back to the saved data point (or drop, if unsaved).
248	        const draft = people?.draftId();
249	        if (saved) for (const f of pstate.filters) if (f.by === draft) f.by = `dp:${model.id}`;
250	        editing = null; panel.hidden = true; people?.setDraft(null); syncPeople(); refresh();
251	      },
252	    });
253	    editing = { model, editor };
254	    people?.setDraft(model);
255	    // While a saved data point is edited, filters on it follow the draft, so sliders change who shows.
256	    const draft = people?.draftId();
257	    if (saved && draft) for (const f of pstate.filters) if (f.by === `dp:${model.id}`) f.by = draft;
258	    syncPeople(draft ?? undefined);
259	    refresh();
260	  }
261	
262	  const blank = (): RiskModel => ({ id: "new_data_point", label: "New data point", baseline: 0.1, odds_ratios: {}, universe: {}, description: "", source: "" });
263	
264	  const handlers = {
265	    onChange: () => { sync3d(); refresh(); },
266	    onNewDatapoint: (preset: RiskModel | null) => {
267	      const m = preset ? { ...JSON.parse(JSON.stringify(preset)) } : blank();
268	      if (isSavedId(m.id)) m.id = `${m.id}_2`;
269	      startEditing(m, false);
270	    },
271	    onEditDatapoint: (id: string) => {
272	      const v = schema.variables.find((x) => x.id === id && x.kind === "datapoint");
273	      if (v?.model) startEditing(v.model, true);
274	    },
275	    onDeleteDatapoint: async (id: string) => {
276	      const v = schema.variables.find((x) => x.id === id);
277	      if (!window.confirm(`Remove the data point "${v?.label ?? id}"? It is deleted from config/datapoints.yaml.`)) return;
278	      await deleteDatapoint(id);
279	      schema = await getSchema();
280	      people?.setSchema(schema);
281	      if (state.variable === id) Object.assign(state, { variable: "population", category: "total", measure: "estimate" });
282	      remountControls();
283	      syncPeople();
284	      refresh();
285	    },
286	    onSearchPick: (hit: { lon: number; lat: number; level: string; area_id: string }) => {
287	      map.flyTo({ center: [hit.lon, hit.lat], zoom: zoomForLevel(schema.levels, hit.level), speed: 1.6 });
288	      if (["county", "state"].includes(hit.level)) return;
289	      map.once("moveend", () => openDetail(hit.level, hit.area_id));
290	    },
291	    onExport: (format: "csv" | "geojson") => { window.location.href = exportUrl(current.level, format, state.filters); },
292	  };
293	  const remountControls = () => { mountControls(document.getElementById("controls")!, schema, state, handlers); mountPeople(); };
294	  remountControls();
295	  sync3d();
296	  getPeople().then((p) => {
297	    people = new PeopleLayer(p, schema);
298	    mainPeople = p;
299	    syncPeople();
300	    getPeopleRuns().then((runs) => {
301	      if (runs.length < 2) return;
302	      player = new Player(document.getElementById("player")!, runs, p,
303	        (frame, run) => { people!.setPeople(frame, run.name); draw(); },
304	        () => { pstate.anyZoom = false; if (mainPeople) people!.setPeople(mainPeople, "main"); draw(); });
305	      mountPeople();
306	    }).catch(() => { /* no saved runs: the player stays hidden */ });
307	  }).catch((e) => { peopleSection.innerHTML = `<h2>People</h2><p class="hint">People are unavailable: ${e.message}</p>`; });
308	
309	  let lastLevel = "";
310	  map.on("load", refresh);
311	  map.on("zoomend", () => {
312	    const level = levelForZoom(schema.levels, map.getZoom()).id;
313	    if (level !== lastLevel) { lastLevel = level; refresh(); }
314	    else {
315	      status.textContent = status.textContent!.replace(/zoom [\d.]+/, `zoom ${map.getZoom().toFixed(1)}`);
316	      draw();
317	    }
318	  });
319	}
320	
321	start().catch((e) => {
322	  document.getElementById("status")!.textContent = `Could not load: ${e.message}. Is the API running (uv run synthpop serve)?`;
323	});
