      const start = new Int32Array(nu + 1);
      for (let i = 0; i < p.count; i++) start[p.unit[i] + 1]++;
      for (let k = 0; k < nu; k++) start[k + 1] += start[k];
      const fill = start.slice(0, nu), list = new Int32Array(p.count);
      for (let i = 0; i < p.count; i++) list[fill[p.unit[i]]++] = i;
      for (let k = 0; k < nu; k++) list.subarray(start[k], start[k + 1]).sort((a, b) => p.head[b] - p.head[a] || p.age[b] - p.age[a] || a - b);
      this.groups = { start, list };
    }
    const { start, list } = this.groups;
    return Array.from(list.subarray(start[u], start[u + 1]));
  }

  /** Visible people (those passing every filter) and their colours, and the households
   * holding anyone visible. A household takes its householder's colour (else its first
   * visible member's); with a data point it is a case when anyone visible in it is. */
  private compute(s: PeopleState): View {
    const key = this.run + JSON.stringify({ ...s, anyZoom: undefined });
    if (this.view?.key === key) return this.view;
    const p = this.p, n = p.count;
    const checks = s.filters.flatMap((f) => {
      const d = this.dim(f.by);
      if (!d) return [];
      const ok = new Set(f.values.map((v) => d.cats.findIndex((c) => c.id === v)));
      return [(i: number) => ok.has(d.code(i))];
    });
    const d = this.dim(s.colorBy) ?? this.dims()[0];
    const pal = this.colours(d);
    const inFocus = s.focus ? this.matcher(s.focus) : null;
    const counts = new Array(d.cats.length + 1).fill(0);
    const vis = new Uint8Array(n), col = new Uint8Array(n * 4), code = new Int16Array(n);
    const keep: number[] = [];
    for (let i = 0; i < n; i++) {
      const c = d.code(i);
      code[i] = c;
      const known = c >= 0 && c < pal.length;
      // Outside a data point's universe (e.g. under 65 for dementia) stays faint, so cases stand out.
      const faint = (d.kind === "datapoint" && c === 2) || (inFocus !== null && !inFocus(i));
      col.set([...(known ? pal[c] : BLANK), faint ? FAINT : SOLID], i * 4);
      if (checks.every((f) => f(i))) { vis[i] = 1; keep.push(i); counts[known ? c : d.cats.length]++; }
    }
    const shown: number[] = [], reps: number[] = [];
    const nu = p.units.r.length;
    this.members(0);
    const { start, list } = this.groups!;
    for (let u = 0; u < nu; u++) {
      let rep = -1;
      for (let j = start[u]; j < start[u + 1]; j++) {
        const i = list[j];
        if (!vis[i]) continue;
        if (d.kind !== "datapoint") { rep = i; break; }
        if (rep < 0 || code[i] < code[rep]) rep = i;      // case before not a case before outside
      }
      if (rep >= 0) { shown.push(u); reps.push(rep); }
    }
    const units = Uint32Array.from(shown);
    const upos = new Float64Array(units.length * 2), ucol = new Uint8Array(units.length * 4), urad = new Float32Array(units.length);
    let households = 0;
    units.forEach((u, k) => {
      upos[k * 2] = p.units.lon[u]; upos[k * 2 + 1] = p.units.lat[u];
      urad[k] = p.units.r[u];
      ucol.set(col.subarray(reps[k] * 4, reps[k] * 4 + 4), k * 4);
      if (p.household[reps[k]] >= 0) households++;
    });
    this.view = { key, idx: Uint32Array.from(keep), vis, col, counts, units, upos, ucol, urad, households };
    return this.view;
  }

  /** A person's colour on the map, as CSS. */
  colour(s: PeopleState, i: number) {
    const c = this.compute(s).col;
    return `rgb(${c[i * 4]},${c[i * 4 + 1]},${c[i * 4 + 2]})`;
  }

  /** Households as circles; the selected one drawn open with its people inside as dots.
   * on.household: a circle was clicked (unit index); on.person: a person dot was clicked. */
  layers(zoom: number, s: PeopleState, on: { household?: (u: number) => void; person?: (i: number) => void } = {}): ScatterplotLayer[] {
    if (!peopleVisible(s, zoom)) return [];
    const v = this.compute(s), p = this.p;
    const out: ScatterplotLayer[] = [new ScatterplotLayer({
      id: "households",
      data: { length: v.units.length, attributes: {
        getPosition: { value: v.upos, size: 2 }, getFillColor: { value: v.ucol, size: 4 }, getRadius: { value: v.urad, size: 1 },
      } },
      radiusUnits: "meters", radiusMinPixels: zoom >= MIN_ZOOM ? 1.5 : 1, billboard: false,
      stroked: zoom >= 15, getLineColor: [255, 255, 255, 230], lineWidthUnits: "pixels", getLineWidth: 0.75,
      pickable: true, autoHighlight: true, highlightColor: [20, 20, 20, 80],
      onClick: (info) => { if (info.index >= 0) on.household?.(v.units[info.index]); },
    })];
    const sel = this.selection;
    if (sel && sel.unit < p.units.r.length) {
      const u = sel.unit, lon = p.units.lon[u], lat = p.units.lat[u], r = p.units.r[u];
      out.push(new ScatterplotLayer({
