        updateTriggers: { getFillColor: v.key, getLineColor: sel.person, getLineWidth: sel.person },
      }));
    }
    return out;
  }

  /** The unit index of a picked household circle. */
  unitAt(pickedIndex: number) { return this.view ? this.view.units[pickedIndex] : -1; }

