// The household card: opens when a household circle is clicked. It says what the household
// is and lists its people (householder first); clicking a person, here or on the map, shows
// everything about them. "Open parcel" opens the parcel in the detail panel.
import type { PeopleLayer, PeopleState } from "./people";

export class HouseholdCard {
  private el: HTMLElement;
  private on: { person: (i: number) => void; close: () => void; parcel: (id: string) => void };
  private key = "";

  constructor(el: HTMLElement, on: HouseholdCard["on"]) {
    this.el = el;
    this.on = on;
  }

  /** Redraw for the layer's selection; hides when nothing is selected. */
  render(layer: PeopleLayer | null, s: PeopleState) {
    const sel = layer?.selection;
    if (!layer || !sel || !s.show) { this.el.hidden = true; this.key = ""; return; }
    const key = `${layer.run}|${sel.unit}|${sel.person}|${JSON.stringify({ ...s, anyZoom: undefined })}`;
    this.el.hidden = false;
    if (key === this.key) return;
    this.key = key;
    const h = layer.householdSummary(sel.unit), p = layer.p;
    const sex = layer.dim("sex");
    const rows = h.members.map((i) => {
      const sx = sex && sex.code(i) >= 0 ? sex.cats[sex.code(i)].label.toLowerCase() : "";
      return `<li><button data-i="${i}" class="${i === sel.person ? "on" : ""}" aria-pressed="${i === sel.person}">
        <i style="background:${layer.colour(s, i)}"></i><span class="hc-role">${layer.role(i)}</span>
        <span>${p.age[i]}${sx ? `, ${sx}` : ""}</span><span class="hc-id">#${i}</span></button></li>`;
    }).join("");
    this.el.innerHTML = `
      <header><b>${h.title}</b> <span class="src">${h.size}</span>
        <button class="ghost tiny hc-close" data-act="close" aria-label="Close household">×</button></header>
      <p class="hc-facts">${h.facts.map(esc).join(" · ")}</p>
      ${h.dps.length ? `<p class="hc-facts">${h.dps.join("<br>")}</p>` : ""}
      <ul class="hc-members">${rows}</ul>
      <div class="hc-person">${sel.person !== null ? layer.tooltip(sel.person) : `<span class="hint">Click a person to see more about them.</span>`}</div>
      <div class="hc-foot"><button class="ghost tiny" data-act="parcel">Open parcel ${esc(h.parcel)}</button></div>`;
    this.el.querySelector<HTMLButtonElement>('[data-act="close"]')!.onclick = () => this.on.close();
    this.el.querySelector<HTMLButtonElement>('[data-act="parcel"]')!.onclick = () => this.on.parcel(h.parcel);
    this.el.querySelectorAll<HTMLButtonElement>(".hc-members button").forEach((b) => (b.onclick = () => this.on.person(+b.dataset.i!)));
  }
}

const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]!);

