    const cols = this.columns();
    const rows = idx.slice(0, limit).map((i) => `<tr>${cols.map(([, f]) => `<td>${esc(String(f(i)))}</td>`).join("")}</tr>`).join("");
    return `<div class="people-table"><table><thead><tr>${cols.map(([h]) => `<th>${esc(h)}</th>`).join("")}</tr></thead><tbody>${rows}</tbody></table></div>
      ${idx.length > limit ? `<p class="hint">Showing ${limit.toLocaleString()} of ${idx.length.toLocaleString()} people. Download the CSV for all of them.</p>` : ""}`;
  }

  /** Counts from the people themselves (one realisation), for the detail panel. */
  summary(idx: number[]) {
    const p = this.p;
    const households = new Set(idx.map((i) => p.household[i]).filter((h) => h >= 0)).size;
    const families = new Set(idx.map((i) => p.family[i]).filter((h) => h >= 0)).size;
    const ages = idx.map((i) => p.age[i]).filter((a) => a >= 0).sort((a, b) => a - b);
    const sex = this.dim("sex");
    const female = sex ? idx.filter((i) => sex.cats[sex.code(i)]?.id === "female").length : 0;
    const dps = this.dims().filter((d) => d.kind === "datapoint").map((d) => {
      const inU = idx.filter((i) => d.code(i) !== 2).length;
      return { label: d.label, cases: idx.filter((i) => d.code(i) === 0).length, universe: inU };
    });
    return { people: idx.length, households, families, medianAge: ages.length ? ages[Math.floor(ages.length / 2)] : null,
      female, groupQuarters: idx.filter((i) => p.household[i] < 0).length, dps };
  }

  /** People passing every filter in the sidebar, in person_id order. */
  visible(s: PeopleState): Uint32Array { return this.compute(s).idx; }

  /** A person's place in their household: householder, relative, not related, or group quarters. */
  role(i: number) {
    const p = this.p;
    return p.household[i] < 0 ? "Group quarters resident" : p.head[i] ? "Householder" : p.family[i] >= 0 ? "Relative" : "Not related";
  }

  /** What a unit is, in words: its kind and size, tenure and family, and cases per data point. */
  householdSummary(u: number) {
    const m = this.members(u), i0 = m[0], p = this.p;
    const label = (id: string, i: number) => { const d = this.dim(id); const c = d ? d.code(i) : -1; return d && c >= 0 ? d.cats[c].label : null; };
    const gq = p.household[i0] < 0;
    const dps = this.dims().filter((d) => d.kind === "datapoint").map((d) => {
      const cases = m.filter((i) => d.code(i) === 0).length, inU = m.filter((i) => d.code(i) !== 2).length;
      return `${d.label}: <b>${cases} case${cases === 1 ? "" : "s"}</b>${inU < m.length ? ` (of ${inU} in the model's universe)` : ""}`;
    });
    return {
      title: gq ? "Group quarters" : `Household ${p.household[i0]}`,
      size: `${m.length} ${gq ? (m.length === 1 ? "resident" : "residents") : m.length === 1 ? "person" : "people"}`,
      facts: gq ? ["Dorm, nursing home, shelter or similar: not a household"]
        : [label("tenure", i0), label("building_type", i0), p.family[i0] >= 0 ? `Family ${p.family[i0]}` : "No family (no relative of the householder)"].filter(Boolean) as string[],
      dps, parcel: p.parcels[p.parcel[i0]], members: m,
    };
  }

  householdTooltip(u: number): string {
    const h = this.householdSummary(u), p = this.p, i0 = h.members[0];
    const who = p.household[i0] < 0 ? "" : `Householder: age ${p.age[i0]}${this.dim("sex") ? ", " + (this.dim("sex")!.cats[this.dim("sex")!.code(i0)]?.label ?? "").toLowerCase() : ""}`;
    return [`<b>${h.title}</b> · ${h.size}`, h.facts.join(" · "), who, ...h.dps, `Parcel ${h.parcel}`,
      `<i>click to see who lives here · one realisation (${this.run === "main" ? "main run" : `run ${this.run}`})</i>`].filter(Boolean).join("<br>");
  }

  tooltip(i: number): string {
    const dims = this.dims();
    const show = (id: string) => {
      const d = dims.find((x) => x.id === id);
      const c = d ? d.code(i) : -1;
      return d && c >= 0 ? d.cats[c].label : null;
    };
    const lines = [
      `<b>Synthetic person</b> · age ${this.p.age[i]}${show("sex") ? ", " + show("sex")!.toLowerCase() : ""}`,
      show("race_eth"), show("education") && `Education: ${show("education")}`,
      show("employment") && `Employment: ${show("employment")!.toLowerCase()}`,
      show("poverty") && `Income: ${this.p.poverty_ratio[i] >= 501 ? "over 500" : this.p.poverty_ratio[i]}% of the poverty line (${show("poverty")!.toLowerCase()})`,
      this.p.household[i] < 0 ? "Group quarters resident" : `${this.role(i)} in household ${this.p.household[i]} · ${(show("tenure") ?? "").toLowerCase()}`,
      ...dims.filter((d) => d.kind === "datapoint").map((d) => `${d.label}: <b>${d.cats[d.code(i)].label.toLowerCase()}</b>`),
      `Person ${i} · ${this.p.family[i] >= 0 ? `family ${this.p.family[i]}` : "not in a family"} · parcel ${this.p.parcels[this.p.parcel[i]]}`,
      `<i>one realisation (${this.run === "main" ? "main run" : `run ${this.run}`})</i>`,
    ];
    return lines.filter(Boolean).join("<br>");
  }

  legend(el: HTMLElement, s: PeopleState, zoom: number) {
    el.hidden = !s.show;
    if (!s.show) return;
    if (!peopleVisible(s, zoom)) { el.innerHTML = `<div class="legend-title">Households</div><div class="legend-note">Zoom in to blocks to see households.</div>`; return; }
    const v = this.compute(s);

