    for (const [codes, lo] of logOr) if (codes && codes[i] >= 0) l += lo[codes[i]];
    out[i] = p.u[i] < 1 / (1 + Math.exp(-l)) ? DATAPOINT.case : DATAPOINT.notCase;
  }
