// is and lists its people (householder first); clicking a person, here or on the map, shows
// everything about them. "Open parcel" opens the parcel in the detail panel.
import type { PeopleLayer, PeopleState } from "./people";

export class HouseholdCard {
  private el: HTMLElement;
  private on: { person: (i: number) => void; close: () => void; parcel: (id: string) => void };
  private key = "";

  constructor(el: HTMLElement, on: HouseholdCard["on"]) {
    this.el = el;
    this.on = on;
  }

  /** Redraw for the layer's selection; hides when nothing is selected. */
  render(layer: PeopleLayer | null, s: PeopleState) {
    const sel = layer?.selection;
    if (!layer || !sel || !s.show) { this.el.hidden = true; this.key = ""; return; }
    const key = `${layer.run}|${sel.unit}|${sel.person}|${JSON.stringify({ ...s, anyZoom: undefined })}`;
    this.el.hidden = false;
    if (key === this.key) return;
    this.key = key;
    const h = layer.householdSummary(sel.unit), p = layer.p;
    const sex = layer.dim("sex");
    const rows = h.members.map((i) => {
      const sx = sex && sex.code(i) >= 0 ? sex.cats[sex.code(i)].label.toLowerCase() : "";
      return `<li><button data-i="${i}" class="${i === sel.person ? "on" : ""}" aria-pressed="${i === sel.person}">
