        if level not in COMPARE_WITH:
            raise KeyError(f"unknown level {level!r}")
        model = RiskModel.parse(raw, self.catalog)
        layer = self._layer_from(self._datapoint_frame(model, level), measure, self._passing(level, filters or []))
